mapper.select:
select mw.*,um.nickname as userName,um.phone as userPhone,um.avatar as userAvatar from ums_withdraw mw left join sys_user um on um.id=mw.user_id where 1 = 1
and mw.user_id = #{paramCondition.userId}
and mw.account_type = #{paramCondition.accountType}
and mw.withdraw_status = #{paramCondition.withdrawStatus}
and ( mw.withdraw_name like CONCAT('%',#{paramCondition.keyword},'%') or mw.withdraw_account like CONCAT('%',#{paramCondition.keyword},'%') or um.phone like CONCAT('%',#{paramCondition.keyword},'%') or um.phone like CONCAT('%',#{paramCondition.keyword},'%') )
order by mw.create_time desc
